# frozen_string_literal: true

# Spike for the chart port: a throwaway Phlex SVG must reproduce the DOM recharts 3.8 renders for a stacked bar chart (the committed
# oracle/bar.html). Decision and the gate contract: dev/decisions/chart.md.
#
#   env -u BUNDLE_GEMFILE bundle exec ruby -Ilib -Itest dev/spikes/chart/bar_chart_test.rb
#
# No browser, no network: the oracle is regenerated by `cd dev/react-shadcn-catalog && node ../spikes/chart/oracle_ssr.mjs`.
require "minitest/autorun"
require_relative "bar_chart"
require_relative "compare"

class BarChartSpikeTest < Minitest::Test
  ORACLE = File.read(File.expand_path("oracle/bar.html", __dir__))
  DATA = [
    { month: "January", desktop: 186, mobile: 80 },
    { month: "February", desktop: 305, mobile: 200 },
    { month: "March", desktop: 237, mobile: 120 },
    { month: "April", desktop: 73, mobile: 190 },
    { month: "May", desktop: 209, mobile: 130 },
    { month: "June", desktop: 214, mobile: 140 }
  ].freeze
  SERIES = [
    ChartSpike::Series.new(:desktop, "Desktop", "var(--chart-1)"),
    ChartSpike::Series.new(:mobile, "Mobile", "var(--chart-2)")
  ].freeze

  def chart(default_index: 1, data: DATA)
    ChartSpike::BarChart.new(id: "spike-bar", data:, series: SERIES, category_key: :month, default_index:)
  end

  def test_matches_the_recharts_dom_within_the_tolerance
    comparison = ChartSpike::Compare.new(ORACLE, chart.call)

    assert_empty comparison.errors
    worst = comparison.max_deviation
    puts "\nbar chart: #{comparison.compared_attributes} numeric attributes compared, largest deviation #{worst.amount} px " \
         "(#{worst.attribute} at #{worst.path}), tolerance #{ChartSpike::Compare::TOLERANCE}"
    assert_operator worst.amount, :<=, ChartSpike::Compare::TOLERANCE
  end

  def test_the_comparison_is_not_vacuous
    # a bar one pixel too tall, a missing class and a changed tag must all be reported
    html = chart.call
    taller = html.sub('height="40.92"', 'height="41.92"')

    refute_equal html, taller
    refute_empty ChartSpike::Compare.new(ORACLE, taller).errors
    refute_empty ChartSpike::Compare.new(ORACLE, html.sub("recharts-bar-rectangles", "recharts-bar-rects")).errors
    refute_empty ChartSpike::Compare.new(ORACLE, html.sub("<title></title>", "<desc></desc>")).errors
  end

  def test_stimulus_wiring_and_chart_templates_are_not_compared
    html = chart.call
    wired = html.sub('<div data-slot="chart"', '<div data-controller="chadcn--chart" data-chadcn--chart-pointer-index-value="1" data-turbo-permanent data-parity-id="c1" data-slot="chart"')
    tooltip = '<template data-chadcn--chart-target="tooltipTemplate" data-index="1"><div>February</div></template>'
    tick = '<template data-chadcn--chart-target="tickTemplate" data-axis="x" data-index="3"><svg><g class="recharts-layer recharts-cartesian-axis-tick-label"></g></svg></template>'
    wired = wired.sub("</style>", "</style>#{tooltip}#{tick}")

    refute_equal html, wired
    assert_empty ChartSpike::Compare.new(ORACLE, wired).errors
    # only the wiring and the two chart templates are exempt: the same attribute on another element, or any other extra child, is a difference
    refute_empty ChartSpike::Compare.new(ORACLE, html.sub("</style>", '</style><div data-chadcn--chart-target="x"></div>')).errors
    refute_empty ChartSpike::Compare.new(ORACLE, html.sub('class="recharts-surface"', 'class="recharts-surface" data-index="1"')).errors
  end

  def test_only_the_two_chart_template_targets_are_exempt
    html = chart.call

    assert_empty ChartSpike::Compare.new(ORACLE, html.sub("</style>", '</style><template data-chadcn--chart-target="tickTemplate" data-axis="x" data-index="0"></template>')).errors
    # a template with another (or no) target, or a template that is not a direct child of div[data-slot=chart], is a difference
    refute_empty ChartSpike::Compare.new(ORACLE, html.sub("</style>", '</style><template data-chadcn--chart-target="other"></template>')).errors
    refute_empty ChartSpike::Compare.new(ORACLE, html.sub("</style>", "</style><template></template>")).errors
    nested = html.sub("<title></title>", '<template data-chadcn--chart-target="tickTemplate"></template><title></title>')
    refute_empty ChartSpike::Compare.new(ORACLE, nested).errors
  end

  def test_url_references_go_through_the_id_table
    layer = '<g tabindex="-1" class="recharts-zIndex-layer_-100">'
    oracle = ORACLE.sub(layer, layer.sub("<g ", '<g clip-path="url(#recharts1-clip)" '))
    html = chart.call
    resolved = html.sub(layer, layer.sub("<g ", '<g clip-path="url(#recharts1-clip)" '))

    refute_equal ORACLE, oracle
    assert_empty ChartSpike::Compare.new(oracle, resolved).errors
    refute_empty ChartSpike::Compare.new(oracle, html.sub(layer, layer.sub("<g ", '<g clip-path="url(#recharts9-clip)" '))).errors
  end

  def test_a_recharts_numeric_axis_uses_get_nice_tick_values_not_d3
    # stacked totals peak at 505: both agree on 0..600; the line example (max 305) is where d3 nice() gives 0..350 and recharts 0..320
    assert_equal [ 0.0, 150.0, 300.0, 450.0, 600.0 ], ChartSpike::NiceTicks.values(0, 505)
    assert_equal [ 0.0, 600.0 ], ChartSpike::D3.nice(0, 505, 5)
    assert_equal [ 0.0, 80.0, 160.0, 240.0, 320.0 ], ChartSpike::NiceTicks.values(0, 305)
    assert_equal [ 0.0, 350.0 ], ChartSpike::D3.nice(0, 305, 5)
    assert_equal [ 0.0, 50.0, 100.0, 150.0, 200.0, 250.0, 300.0, 350.0 ], ChartSpike::D3.ticks(0, 350, 5)
  end

  def test_geometry_of_the_stack_and_the_bands
    built = chart
    rects = built.rectangles

    assert_equal 12, rects.size
    assert_in_delta 51.6667, built.band.step, 1e-4
    assert_equal 41, rects.first[:width] # (51.67 - 2 * 5.17) truncated like `originalSize >> 0`
    # the mobile series starts where the desktop one ends
    assert_in_delta rects[0][:y], rects[6][:y] + rects[6][:height], 1e-9
  end

  def test_without_default_index_there_is_no_cursor_and_the_tooltip_is_hidden
    html = chart(default_index: nil).call

    refute_includes html, "recharts-rectangle recharts-tooltip-cursor"
    assert_includes html, "visibility: hidden"
  end

  def test_other_data_stays_structurally_consistent
    data = DATA.map { |row| row.merge(desktop: row[:desktop] * 2, mobile: row[:mobile] * 3) } # totals up to 1010 -> 0..1200
    html = chart(data:).call

    assert_equal [ 0.0, 300.0, 600.0, 900.0, 1200.0 ], ChartSpike::NiceTicks.values(0, 1010)
    assert_equal 12, html.scan("recharts-bar-rectangle\"").size
  end
end
